{
  "$schema": "https://agent-plugins.org/schemas/1.0.0/plugin.schema.json",
  "name": "a-bioma-doc-standard",
  "version": "2.1.0",
  "description": "Analisa, organiza e padroniza documentação de projetos em Markdown com Diátaxis, arc42 simplificado, C4, MADR e escrita Microsoft/ISO.",
  "author": {
    "name": "Silvio Barbosa",
    "email": "ssfbarbosa@outlook.com"
  },
  "keywords": [
    "documentacao",
    "docs-as-code",
    "diataxis",
    "arc42",
    "c4",
    "markdown",
    "adr",
    "github"
  ],
  "extensions": {
    "com.openai": {
      "interface": {
        "displayName": "A-Bioma Doc Standard",
        "shortDescription": "Padronizar documentação",
        "longDescription": "Audita ou estrutura a documentação Markdown de projetos de software. Usa organização Diátaxis, arquitetura arc42/C4, ADRs, contratos técnicos e escrita clara, com rastreabilidade e sem redundância.",
        "developerName": "Silvio Barbosa",
        "category": "Productivity",
        "capabilities": [
          "Interactive"
        ],
        "defaultPrompt": [
          "Analise a documentação deste repositório e proponha a estrutura A-Bioma Doc Standard 1.0, sem editar arquivos ainda.",
          "Aplique o padrão A-Bioma Doc Standard 1.0 na documentação deste repositório, usando a branch develop e sem alterar código-fonte.",
          "Revise a escrita e as referências cruzadas dos arquivos de /docs segundo o padrão A-Bioma."
        ]
      }
    }
  }
}

